const contentId = String($json.content_id ?? '').trim();
if (!contentId) {
  throw new Error('Manual callback path could not find a queued render content_id.');
}
const renderLogText = String($json.render_log ?? '').trim();
let parsedRenderLog = {};
if (renderLogText) {
  try {
    parsedRenderLog = JSON.parse(renderLogText);
  } catch {}
}
const outputPath = String(parsedRenderLog?.request?.storage?.output_path || `reels/${contentId}/final.mp4`).trim();
const outputBase = String($env.RENDER_CALLBACK_OUTPUT_BASE_URL || $env.REELS_STORAGE_PUBLIC_BASE_URL || '').trim().replace(/\/$/, '');
const outputVideoUrl = outputBase ? `${outputBase}/${outputPath}` : `https://example.com/${outputPath}`;
return [{
  json: {
    content_id: contentId,
    render_status: 'success',
    output_video_url: outputVideoUrl,
    cover_image_url: String($json.cover_image_url ?? '').trim(),
    duration_seconds: Number($json.duration_seconds ?? 0),
    resolution: String($json.resolution ?? '').trim(),
    render_log: 'stub render completed locally',
    error_message: '',
    workflow_name: 'wf_render_status_callback',
    run_started_at: new Date().toISOString()
  }
}];

const sourceJson = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const contentId = String(sourceJson.content_id ?? '').trim();
const renderStatus = String(sourceJson.render_status ?? '').trim().toLowerCase();
if (!contentId) {
  throw new Error('content_id is required for the render status callback.');
}
if (!['success', 'failed'].includes(renderStatus)) {
  throw new Error('render_status must be either success or failed.');
}
return [{
  json: {
    content_id: contentId,
    render_status: renderStatus,
    output_video_url: String(sourceJson.output_video_url ?? '').trim(),
    cover_image_url: String(sourceJson.cover_image_url ?? '').trim(),
    duration_seconds: Number(sourceJson.duration_seconds ?? 0),
    resolution: String(sourceJson.resolution ?? '').trim(),
    render_log: String(sourceJson.render_log ?? '').trim(),
    error_message: String(sourceJson.error_message ?? '').trim(),
    workflow_name: 'wf_render_status_callback',
    run_started_at: new Date().toISOString()
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Render status callback received an invalid content_id: ' + (contentId || '<empty>') + '.');
}
const renderStatus = String($json.render_status ?? '').trim().toLowerCase();
const isSuccess = renderStatus === 'success';
const nextContentStatus = isSuccess ? 'render_complete' : 'render_failed';
const nextRenderStatus = isSuccess ? 'success' : 'failed';
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
const callbackSummary = {
  render_status: nextRenderStatus,
  output_video_url: String($json.output_video_url ?? '').trim(),
  cover_image_url: String($json.cover_image_url ?? '').trim(),
  duration_seconds: Number.isFinite(Number($json.duration_seconds)) ? Number($json.duration_seconds) : 0,
  resolution: String($json.resolution ?? '').trim(),
  error_message: String($json.error_message ?? '').trim()
};
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    next_content_status_sql: nextContentStatus,
    next_render_status_sql: nextRenderStatus,
    output_video_url_sql: String($json.output_video_url ?? '').replaceAll("'", "''"),
    cover_image_url_sql: String($json.cover_image_url ?? '').replaceAll("'", "''"),
    duration_seconds_sql: Number.isFinite(Number($json.duration_seconds)) ? Number($json.duration_seconds) : 0,
    resolution_sql: String($json.resolution ?? '').replaceAll("'", "''"),
    render_log_sql: String($json.render_log ?? '').replaceAll("'", "''"),
    error_message_sql: String($json.error_message ?? '').replaceAll("'", "''"),
    workflow_name_sql: String($json.workflow_name ?? 'wf_render_status_callback').replaceAll("'", "''"),
    callback_summary_json_sql: JSON.stringify(callbackSummary).replaceAll("'", "''"),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0
  }
}];
